}

ul {
    list-style: none;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.section {
    padding: 5rem 0;
}

.section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2.5rem;
}

.section__title {
    font-size: 2rem;
    font-weight: 600;
}

.link {
    font-weight: 500;
    border-bottom: 2px solid var(--primary);
    padding-bottom: 2px;
}

/* Header */
.header {
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(10px);
    z-index: 1000;
    border-bottom: 1px solid #eee;
}

.header__wrapper {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.header__logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.header__nav {
    display: flex;
    gap: 2rem;
}

.header__nav a {
    font-weight: 500;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.header__actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--text);
    transition: var(--transition);
}

.icon-btn:hover {
    color: var(--accent);
}

/* Hero */
.hero {
    height: 80vh;
    background: linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.3)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    color: var(--white);
    text-align: center;
}

.hero__content {
    max-width: 700px;
}

.hero__subtitle {
    display: block;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 3px;
    margin-bottom: 1rem;
}

.hero__title {
    font-size: 4rem;
    font-weight: 700;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

.hero__description {
    font-size: 1.2rem;
    margin-bottom: 2.5rem;
    opacity: 0.9;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 0.8rem;
    border: none;
    cursor: pointer;
    transition: var(--transition);
}

.btn--primary {
    background: var(--primary);
    color: var(--white);
}

.btn--primary:hover {
    background: #333;
}

.btn--white {
    background: var(--white);
    color: var(--primary);
}

.btn--white:hover {
    background: var(--secondary);
}

.btn--outline {
    background: transparent;
    border: 1px solid var(--primary);
    color: var(--primary);
}

.btn--outline:hover {
    background: var(--primary);
    color: var(--white);
}

/* Products */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    group: hover;
}

.product-card__image {
    aspect-ratio: 4/5;
    background: var(--secondary);
    margin-bottom: 1rem;
    overflow: hidden;
    position: relative;
}

.product-card__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-card__image img {
    transform: scale(1.05);
}

.product-card__info {
    text-align: center;
}

.product-card__tag {
    font-size: 0.7rem;
    text-transform: uppercase;
    color: var(--text-light);
    margin-bottom: 0.3rem;
    display: block;
}

.product-card__name {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 0.5rem;
}

.product-card__price {
    font-weight: 600;
}

/* Deals */
.deals__banner {
    background: var(--primary);
    color: var(--white);
    padding: 5rem 2rem;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.deals__title {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals__text {
    font-size: 1.1rem;
    margin-bottom: 2rem;
    opacity: 0.8;
}

.countdown {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin-bottom: 3rem;
}

.countdown__item {
    display: flex;
    flex-direction: column;
}

.countdown__item span:first-child {
    font-size: 2.5rem;
    font-weight: 700;
}

.countdown__item span:last-child {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    opacity: 0.6;
}

/* Editorial */
.editorial__wrapper {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial__image {
    aspect-ratio: 1/1;
}

.editorial__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial__title {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial__text {
    margin-bottom: 2rem;
    color: var(--text-light);
}

/* Footer */
.footer {
    background: var(--secondary);
    padding: 5rem 0 2rem;
}

.footer__grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 3rem;
    margin-bottom: 4rem;
}

.footer__logo {
    font-size: 1.5rem;
    font-weight: 800;
    margin-bottom: 1.5rem;
}

.footer__col h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 1px;
}

.footer__col ul li {
    margin-bottom: 0.8rem;
}

.footer__col ul li a {
    color: var(--text-light);
}

.footer__col ul li a:hover {
    color: var(--primary);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border: 1px solid #ddd;
    outline: none;
}

.newsletter-form button {
    padding: 0.8rem 1.5rem;
    background: var(--primary);
    color: var(--white);
    border: none;
    cursor: pointer;
}

.footer__bottom {
    border-top: 1px solid #ddd;
    padding-top: 2rem;
    text-align: center;
    font-size: 0.9rem;
    color: var(--text-light);
}

/* Responsive */
@media (max-width: 968px) {
    .hero__title {
        font-size: 3rem;
    }
    .footer__grid {
        grid-template-columns: 1fr 1fr;
    }
    .editorial__wrapper {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .editorial__image {
        order: 2;
    }
}

@media (max-width: 600px) {
    .header__nav {
        display: none;
    }
    .hero__title {
        font-size: 2.5rem;
    }
    .footer__grid {
        grid-template-columns: 1fr;
    }
    .countdown {
        gap: 1rem;
    }
    .countdown__item span:first-child {
        font-size: 1.5rem;
    }
